if [[ -n "$ARGC_COMPLETIONS_ROOT" && -f "$ARGC_COMPLETIONS_ROOT/utils/_argc_utils.sh" ]]; then
    . "$ARGC_COMPLETIONS_ROOT/utils/_argc_utils.sh"
fi

_choice_container() {
    if command -v docker >/dev/null 2>&1; then
        docker ps --format '{{.Names}}\t{{.Image}}' 2>/dev/null
    elif command -v podman >/dev/null 2>&1; then
        podman ps --format '{{.Names}}\t{{.Image}}' 2>/dev/null
    fi
}

_choice_pid() {
    ps -Ao pid=,args= 2>/dev/null | gawk '{
        pid = $1
        desc = $0
        sub(/^[[:space:]]*/, "", desc)
        sub(/^[^[:space:]]+[[:space:]]+/, "", desc)
        if (length(desc) > 70) {
            desc = substr(desc, 1, 67) "..."
        }
        if (desc == "") {
            print pid
        } else {
            printf "%s\t%s\n", pid, desc
        }
    }'
}

_choice_port() {
    if command -v ss >/dev/null 2>&1; then
        ss -lntuH 2>/dev/null | gawk '{
            n = split($5, parts, ":")
            if (n > 1 && parts[n] != "") {
                print parts[n]
            }
        }'
    elif command -v lsof >/dev/null 2>&1; then
        lsof -nP -iTCP -sTCP:LISTEN 2>/dev/null | gawk 'NR > 1 {
            addr = $9
            sub(/[[:space:]].*/, "", addr)
            n = split(addr, parts, ":")
            if (n > 1 && parts[n] != "") {
                print parts[n]
            }
        }'
    fi
}

_choice_process() {
    ps -Ao comm=,args= 2>/dev/null | gawk '{
        comm = $1
        sub(/^[[:space:]]*/, "", comm)
        args = $0
        sub(/^[[:space:]]*[^[:space:]]+[[:space:]]+/, "", args)
        sub(/[[:space:]].*/, "", args)
        sub(/.*\//, "", args)
        if (comm != "" && comm !~ /^\[/) {
            print comm
        }
        if (args != "" && args !~ /^\[/) {
            print args
        }
    }'
}
